def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos usando notación sustractiva."""
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    romanos = [
        (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
        (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
        (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")
    ]

    result = []
    for value, symbol in romanos:
        while n >= value:
            result.append(symbol)
            n -= value

    return ''.join(result)

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    longitud = 1

    for i in range(1, len(lista)):
        if lista[i] == max_elemento:
            longitud += 1
        else:
            if longitud > max_racha:
                max_racha = longitud
                max_elemento = lista[i]
                longitud = 1

    if longitud > max_racha:
        max_racha = longitud
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra se convierte en minúscula y las siguientes
    en mayúscula inicial, sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if len(word) == 1:
                result.append(word)
            else:
                result.append(word[0].upper() + word[1:])
    return " ".join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []

    primos = []
    for i in range(2, n + 1):
        es_primo = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(i)

    return primos

def fusionar(intervalos: list[tuple[int, int]]) -> list[tuple[int, int]]:
    """
    Recibe una lista de tuplas (inicio, fin) y devuelve la lista de intervalos
    fusionados, ordenados por inicio. Dos intervalos se fusionan si se tocan,
    es decir, si el inicio del segundo es igual o igual al fin del primero.

    Ejemplo:
        fusionar([(1, 3), (3, 5), (5, 7)]) -> [(1, 7)]
    """
    if not intervals:
        return []

    result = []
    for inicio, fin in intervals:
        if not result:
            result.append((inicio, fin))
        elif inicio <= result[-1][1]:
            # Se tocan o se superponen, fusionar
            result[-1] = (min(result[-1][0], inicio), max(result[-1][1], fin))
        else:
            result.append((inicio, fin))

    return result

def anidar(plano: dict) -> dict:
    """
    Recibe un dict de claves con puntos y lo convierte en un dict anidado.

    Ejemplo: {'a.b': 1} -> {'a': {'b': 1}}

    Args:
        plano: Un diccionario donde las claves son strings que contienen puntos '.'

    Returns:
        Un diccionario anidado donde cada nivel de puntos se convierte en un nuevo nivel.
    """
    if not plano:
        return {}

    result = {}
    for key, value in plano.items():
        if '.' in key:
            # Recursión: dividir la clave en partes por puntos
            parts = key.split('.')
            # El primer elemento es la clave actual, el resto son los niveles
            nested = {parts[0]: value}
            for part in parts[1:]:
                nested[part] = nested[part]
            result[key] = nested
        else:
            result[key] = value

    return result

def formatear_bytes(n: int) -> str:
    """Convierte un número de bytes a texto legible usando múltiplos de 1024.

    Unidades: B, KB, MB, GB.
    B va sin decimales, KB, MB, GB van con decimales.

    Args:
        n: Número entero en bytes.

    Returns:
        String representando el tamaño en formato legible.
    """
    if n <= 0:
        return "0 B"

    if n <= 1024:
        return f"{n} B"
    elif n <= 1024 * 1024:
        return f"{n / 1024:.1f} KB"
    elif n <= 1024 * 1024 * 1024:
        return f"{n / 1024 / 1024:.1f} MB"
    else:
        return f"{n / 1024 / 1024 / 1024:.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}

    result = {}
    current_key = None
    current_value = None

    for char in s:
        if char == '&':
            if current_key is not None:
                result[current_key] = current_value
            current_key = None
            current_value = None
        elif char == '=':
            if current_key is not None:
                current_value = current_value + char
            else:
                current_key = char
        else:
            if current_key is not None:
                current_value = current_value + char

    if current_key is not None:
        result[current_key] = current_value

    return result

def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en formato romano.

    Args:
        a: Primer número en formato romano.
        b: Segundo número en formato romano.

    Returns:
        El resultado de la suma en formato romano.

    Raises:
        ValueError: Si los números no son válidos en formato romano.
    """
    def valor_romano(num: str) -> int:
        """Convierte un número romano a entero."""
        if not num:
            raise ValueError("El número romano no es válido.")
        if len(num) > 4:
            raise ValueError("El número romano no es válido.")
        if num[0] == 'I':
            return -1 + int(num[1:])
        elif num[0] == 'V':
            return 5 + int(num[1:])
        elif num[0] == 'X':
            return 10 + int(num[1:])
        elif num[0] == 'L':
            return 50 + int(num[1:])
        elif num[0] == 'C':
            return 100 + int(num[1:])
        elif num[0] == 'D':
            return 500 + int(num[1:])
        elif num[0] == 'M':
            return 1000 + int(num[1:])
        else:
            raise ValueError("El número romano no es válido.")

    try:
        a_val = valor_romano(a)
        b_val = valor_romano(b)
    except ValueError:
        raise ValueError("Ambos números deben ser válidos en formato romano.")

    if a_val > b_val:
        return valor_romano(str(a_val - b_val))
    else:
        return valor_romano(str(b_val - a_val))
